const Upgrade=(()=>{
 let soundContext,successBuffer,successSource;
 function prepareSound(){try{soundContext??=new(window.AudioContext||window.webkitAudioContext)();soundContext.resume().catch(()=>{});if(successSource){try{successSource.stop();}catch{}successSource=null;}successBuffer??=fetch('assets/upgrade-success.mp3').then(r=>{if(!r.ok)throw Error('Audio unavailable');return r.arrayBuffer();}).then(data=>soundContext.decodeAudioData(data)).catch(()=>{successBuffer=null;return null;});}catch{}}
 function playSuccess(){if(!successBuffer)return;successBuffer.then(buffer=>{if(!buffer)return;const source=soundContext.createBufferSource();source.buffer=buffer;source.connect(soundContext.destination);successSource=source;source.start();}).catch(()=>{});}
 let sourceId=null,targetName=null,last=null,rolling=null;
 const catalog=[...new Map(Game.cases.flatMap(c=>Game.getItems(c)).filter(x=>x.type!=='currency').map(x=>[x.name,x])).values()].sort((a,b)=>a.value-b.value);
 function chance(ratio){return Number.isFinite(ratio)&&ratio>=1.2?Math.min(.55,.66/ratio):0;}
 function card(item,selected,attribute){return `<button class="upgrade-item ${selected?'selected':''} ${item.rarity}" ${attribute}><span>${itemVisual(item)}</span><b>${item.name}</b><small>${item.value} VPN</small></button>`;}
 function draw(){const source=rolling?.source||state.inventory.find(x=>x.id===sourceId);if(!source)sourceId=null;const targets=source?catalog.filter(x=>x.value>=source.value*1.2):[];const target=rolling?.target||targets.find(x=>x.name===targetName);if(!target)targetName=null;const ratio=target&&source?target.value/source.value:0,p=chance(ratio);
 $('#main').innerHTML=`<div class="page-heading"><div class="eyebrow">ПОДНИМИ ПЛАНКУ</div><h1>Апгрейд <em>↑</em></h1><p>Выбери предмет и цель. Чем выше коэффициент, тем ниже шанс.</p></div><section class="upgrade-machine"><div class="upgrade-slot">${source?itemVisual(source):'＋'}<b>${source?source.name:'Твой предмет'}</b></div><div class="upgrade-center"><div class="upgrade-dial ${rolling?'is-rolling':''} ${last?(last.won?'dial-win':'dial-loss'):''}" style="--arc:${(rolling?.p||p)*360}deg;--end:${rolling?rolling.angle:0}deg"><div class="dial-needle"></div><span>${rolling?'↑':last?(last.won?'✦':'×'):'↑'}</span></div><strong>${p?(p*100).toLocaleString('ru',{maximumFractionDigits:2})+'%':'55% max'}</strong><span>${ratio?'×'+ratio.toLocaleString('ru',{maximumFractionDigits:2}):'От ×1,2'}</span><div class="upgrade-meter"><i style="width:${p*100}%"></i></div><button class="primary wide" id="upgradeGo" ${!p||busy?'disabled':''}>${busy?'Проверяем удачу…':'Улучшить предмет'}</button></div><div class="upgrade-slot">${target?itemVisual(target):'◇'}<b>${target?target.name:'Цель улучшения'}</b></div></section><p class="fine">При успехе исходный предмет заменяется на цель. При проигрыше исходный предмет сгорает. Монеты за попытку не списываются. Минимум ×1,2 — 55%; шанс = 66% ÷ коэффициент.</p>${last?`<div class="upgrade-reveal ${last.won?'win':'loss'}" role="status"><div class="reveal-art">${itemVisual(last.won?last.target:last.source)}</div><div><span>${last.won?'АПГРЕЙД УДАЛСЯ':'ПРЕДМЕТ СГОРЕЛ'}</span><h2>${last.won?last.target.name:last.source.name}</h2><p>${last.won?'Новый предмет уже в инвентаре':'Попробуй с другим предметом'}</p></div></div>`:''}<div class="upgrade-columns"><section><h2>1. Твой инвентарь</h2><div class="upgrade-grid">${state.inventory.length?state.inventory.map(it=>card(it,it.id===sourceId,`data-source="${it.id}"`)).join(''):'<p class="fine">Пока пусто. Сначала получи предметы из кейсов.</p>'}</div></section><section><h2>2. Цель улучшения</h2><div class="upgrade-grid">${targets.length?targets.map(it=>card(it,it.name===targetName,`data-target="${catalog.indexOf(it)}"`)).join(''):`<p class="fine">${source?'Для этого предмета пока нет более дорогих целей.':'Сначала выбери предмет слева.'}</p>`}</div></section></div>`;
 $('#main').querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{if(busy)return;sourceId=b.dataset.source;targetName=null;last=null;draw();});$('#main').querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{if(busy)return;targetName=catalog[Number(b.dataset.target)].name;last=null;draw();});$('#upgradeGo').onclick=attempt;
 }
 function attempt(){if(busy)return;const idx=state.inventory.findIndex(x=>x.id===sourceId),target=catalog.find(x=>x.name===targetName);if(idx<0||!target)return;const source=state.inventory[idx],p=chance(target.value/source.value);if(!p)return;prepareSound();busy=true;const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);const roll=bytes[0]/4294967296;const won=roll<p;rolling={source:{...source},target:{...target},p,angle:1800+roll*360};state.inventory.splice(idx,1);if(won)state.inventory.push({...target,id:crypto.randomUUID()});save();sourceId=null;targetName=null;last=null;draw();setTimeout(()=>{busy=false;if(won)playSuccess();rolling=null;last={won,name:target.name,source,target};if(page==='upgrade')draw();else toast(won?'Апгрейд успешен: '+target.name:'Апгрейд не удался — предмет сгорел');},3100);}
 const originalRender=render;render=function(){originalRender();if(page==='upgrade')draw();};
 return {chance};
})();

